   131→
   132→    impl Log {
   133→        /// Attempts to parse a raw `Log` from the deposit contract into a `DepositLog`.
   134→        pub fn to_deposit_log(&self, spec: &ChainSpec) -> Result<DepositLog, String> {
   135→            let bytes = &self.data;
   136→
   137→            let pubkey = bytes
   138→                .get(PUBKEY_START..PUBKEY_START + PUBKEY_LEN)
   139→                .ok_or("Insufficient bytes for pubkey")?;
   140→            let withdrawal_credentials = bytes
   141→                .get(CREDS_START..CREDS_START + CREDS_LEN)
   142→                .ok_or("Insufficient bytes for withdrawal credential")?;
   143→            let amount = bytes
   144→                .get(AMOUNT_START..AMOUNT_START + AMOUNT_LEN)
   145→                .ok_or("Insufficient bytes for amount")?;
   146→            let signature = bytes
   147→                .get(SIG_START..SIG_START + SIG_LEN)
   148→                .ok_or("Insufficient bytes for signature")?;
   149→            let index = bytes
   150→                .get(INDEX_START..INDEX_START + INDEX_LEN)
   151→                .ok_or("Insufficient bytes for index")?;
   152→
   153→            let deposit_data = DepositData {
   154→                pubkey: PublicKeyBytes::from_ssz_bytes(pubkey)
   155→                    .map_err(|e| format!("Invalid pubkey ssz: {:?}", e))?,
   156→                withdrawal_credentials: Hash256::from_ssz_bytes(withdrawal_credentials)
   157→                    .map_err(|e| format!("Invalid withdrawal_credentials ssz: {:?}", e))?,
   158→                amount: u64::from_ssz_bytes(amount)
   159→                    .map_err(|e| format!("Invalid amount ssz: {:?}", e))?,
   160→                signature: SignatureBytes::from_ssz_bytes(signature)
   161→                    .map_err(|e| format!("Invalid signature ssz: {:?}", e))?,
   162→            };
   163→
   164→            let signature_is_valid = deposit_pubkey_signature_message(&deposit_data, spec)
   165→                .is_some_and(|(public_key, signature, msg)| signature.verify(&public_key, msg));
   166→
   167→            Ok(DepositLog {
   168→                deposit_data,
   169→                block_number: self.block_number,
   170→                index: u64::from_ssz_bytes(index)
   171→                    .map_err(|e| format!("Invalid index ssz: {:?}", e))?,
   172→                signature_is_valid,
   173→            })
   174→        }
   175→    }
