286-/// Verifies the `randao_reveal` against the block's proposer pubkey and updates
287-/// `state.latest_randao_mixes`.
288-pub fn process_randao<E: EthSpec, Payload: AbstractExecPayload<E>>(
289-    state: &mut BeaconState<E>,
290-    block: BeaconBlockRef<'_, E, Payload>,
291-    verify_signatures: VerifySignatures,
292-    ctxt: &mut ConsensusContext<E>,
293-    spec: &ChainSpec,
294-) -> Result<(), BlockProcessingError> {
295-    if verify_signatures.is_true() {
296-        // Verify RANDAO reveal signature.
297-        let proposer_index = ctxt.get_proposer_index(state, spec)?;
298-        block_verify!(
299-            randao_signature_set(
300-                state,
301-                |i| get_pubkey_from_state(state, i),
302-                block,
303-                Some(proposer_index),
304-                spec
305-            )?
306-            .verify(),
307-            BlockProcessingError::RandaoSignatureInvalid
308-        );
309-    }
310-
311-    // Update the current epoch RANDAO mix.
312-    state.update_randao_mix(state.current_epoch(), block.body().randao_reveal())?;
313-
314-    Ok(())
315-}
